mapper.select:
SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, db.name AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
ORDER BY wm.sys_classify,wm.id

SELECT max(wmrs.id) id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, '' AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
GROUP BY wm.sys_classify, wm.module_classify ORDER BY sys_classify,max(wmrs.id)

SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wm.module_code AS moduleCode, db.name AS moduleStatusName, wmrs.module_status AS moduleStatus, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.type = '1'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wmrs.id, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.type = '2'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id
